/* eslint-disable max-params */

'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var floor = require( '@stdlib/math/base/special/floor' );
var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
var gindexOfGreaterThan = require( '@stdlib/blas/ext/base/gindex-of-greater-than' ).ndarray;
var gindexOfGreaterThanEqual = require( '@stdlib/blas/ext/base/gindex-of-greater-than-equal' ).ndarray;
var gindexOfLessThan = require( '@stdlib/blas/ext/base/gindex-of-less-than' ).ndarray;
var gindexOfLessThanEqual = require( '@stdlib/blas/ext/base/gindex-of-less-than-equal' ).ndarray;
var format = require( '@stdlib/string/format' );
var accessors = require( './accessors.js' );


// FUNCTIONS //

/**
* Finds insertion indices by performing a linear search for each search element.
*
* @private
* @param {NonNegativeInteger} M - number of indexed elements in `x` and `out`
* @param {NonNegativeInteger} N - number of indexed elements in `search`
* @param {Function} fcn - linear search function
* @param {Collection} x - input array containing search elements
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Collection} search - sorted input array
* @param {integer} strideSearch - stride length for `search`
* @param {NonNegativeInteger} offsetSearch - starting index for `search`
* @param {Collection} out - output array
* @param {integer} strideOut - stride length for `out`
* @param {NonNegativeInteger} offsetOut - starting index for `out`
* @returns {Collection} output array
*/
function linear( M, N, fcn, x, strideX, offsetX, search, strideSearch, offsetSearch, out, strideOut, offsetOut ) { // eslint-disable-line max-len
	var idx;
	var ix;
	var io;
	var q;
	var i;

	ix = offsetX;
	io = offsetOut;
	for ( i = 0; i < M; i++ ) {
		q = x[ ix ];

		// If the search element is `NaN`, set the insertion index to `-1`...
		if ( isnan( q ) ) {
			out[ io ] = -1;
		} else {
			idx = fcn( N, q, search, strideSearch, offsetSearch );
			out[ io ] = ( idx < 0 ) ? N : idx;
		}
		ix += strideX;
		io += strideOut;
	}
	return out;
}


// MAIN //

/**
* Finds the indices at which elements should be inserted into a sorted strided array in order to maintain sort order using alternative indexing semantics.
*
* ## Notes
*
* -   For each element in `x`, the function writes to `out` an index in the interval `[0, N]` such that inserting the element into `search` at that index preserves sort order.
* -   If `side` is `'left'`, each index is the position of the first element in `search` which is greater than or equal to the search element (ascending order) or less than or equal to the search element (descending order).
* -   If `side` is `'right'`, each index is the position of the first element in `search` which is strictly greater than the search element (ascending order) or strictly less than the search element (descending order).
* -   If a search element is `NaN`, the function writes `-1` to the corresponding element in `out`.
*
* @param {NonNegativeInteger} M - number of indexed elements in `x` and `out`
* @param {NonNegativeInteger} N - number of indexed elements in `search`
* @param {string} side - insertion side (`'left'` or `'right'`)
* @param {Collection} x - input array containing search elements
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Collection} search - sorted input array
* @param {integer} strideSearch - stride length for `search`
* @param {NonNegativeInteger} offsetSearch - starting index for `search`
* @param {Collection} out - output array
* @param {integer} strideOut - stride length for `out`
* @param {NonNegativeInteger} offsetOut - starting index for `out`
* @throws {TypeError} third argument must be a valid side
* @returns {Collection} output array
*
* @example
* var search = [ 1.0, 2.0, 2.0, 3.0 ];
* var x = [ 0.0, 2.0, 4.0 ];
* var out = [ 0, 0, 0 ];
*
* gsearchSorted( x.length, search.length, 'left', x, 1, 0, search, 1, 0, out, 1, 0 );
* // out => [ 0, 1, 4 ]
*/
function gsearchSorted( M, N, side, x, strideX, offsetX, search, strideSearch, offsetSearch, out, strideOut, offsetOut ) { // eslint-disable-line max-len
	var isRight;
	var length;
	var isAsc;
	var half;
	var base;
	var fcn;
	var mid;
	var ix;
	var io;
	var ox;
	var os;
	var oo;
	var v1;
	var v2;
	var a;
	var b;
	var q;
	var v;
	var i;

	if ( side !== 'left' && side !== 'right' ) {
		throw new TypeError( format( 'invalid argument. Third argument must be a valid side. Value: `%s`.', side ) );
	}
	if ( M <= 0 ) {
		return out;
	}
	ox = arraylike2object( x );
	os = arraylike2object( search );
	oo = arraylike2object( out );
	if ( ox.accessorProtocol || os.accessorProtocol || oo.accessorProtocol ) {
		accessors( M, N, side, ox, strideX, offsetX, os, strideSearch, offsetSearch, oo, strideOut, offsetOut ); // eslint-disable-line max-len
		return out;
	}
	// If the sorted array is empty, every search element should be inserted at index `0`, except for `NaN` search elements (note: we explicitly pass `0` for `N` in order to accommodate negative `N`)...
	if ( N <= 0 ) {
		return linear( M, 0, gindexOfGreaterThanEqual, x, strideX, offsetX, search, strideSearch, offsetSearch, out, strideOut, offsetOut ); // eslint-disable-line max-len
	}
	isRight = ( side === 'right' );

	v1 = search[ offsetSearch ];
	v2 = search[ offsetSearch + ( ( N - 1 ) * strideSearch ) ];

	// If either the first or last indexed element is NaN, we cannot determine the sort order, so assume ascending order and fall back to a linear search...
	if ( isnan( v1 ) || isnan( v2 ) ) {
		fcn = ( isRight ) ? gindexOfGreaterThan : gindexOfGreaterThanEqual;
		return linear( M, N, fcn, x, strideX, offsetX, search, strideSearch, offsetSearch, out, strideOut, offsetOut ); // eslint-disable-line max-len
	}
	isAsc = ( v1 <= v2 );
	if ( isAsc ) {
		fcn = ( isRight ) ? gindexOfGreaterThan : gindexOfGreaterThanEqual;
	} else {
		fcn = ( isRight ) ? gindexOfLessThan : gindexOfLessThanEqual;
	}
	// Perform all binary searches simultaneously, advancing each search by one level at a time. Each search is described by a lower bound `base` (stored in `out`) and a shared interval length `length`, such that the insertion index for the corresponding search element is in `[base, base+length]`. An element of `search` is "before" the insertion index when it is less than (ascending order) or greater than (descending order) the search element. When `side` is `'right'`, elements equal to the search element are also considered "before" the insertion index.

	// First level: as every lower bound is `0`, all searches share the same pivot element, so we can write to `out` directly...
	length = N;
	half = floor( length / 2 );
	v = search[ offsetSearch + ( half * strideSearch ) ];
	if ( isnan( v ) ) {
		return linear( M, N, fcn, x, strideX, offsetX, search, strideSearch, offsetSearch, out, strideOut, offsetOut ); // eslint-disable-line max-len
	}
	ix = offsetX;
	io = offsetOut;
	for ( i = 0; i < M; i++ ) {
		q = x[ ix ];
		if ( isAsc ) {
			a = v;
			b = q;
		} else {
			a = q;
			b = v;
		}
		out[ io ] = ( ( isRight ) ? ( a <= b ) : ( a < b ) ) ? half : 0;
		ix += strideX;
		io += strideOut;
	}
	length -= half;

	// Remaining levels: advance each search by halving its interval...
	while ( length > 1 ) {
		half = floor( length / 2 );
		ix = offsetX;
		io = offsetOut;
		for ( i = 0; i < M; i++ ) {
			base = out[ io ];
			mid = base + half;
			v = search[ offsetSearch + ( mid * strideSearch ) ];

			// If we encounter a NaN, fall back to a linear search...
			if ( isnan( v ) ) {
				return linear( M, N, fcn, x, strideX, offsetX, search, strideSearch, offsetSearch, out, strideOut, offsetOut ); // eslint-disable-line max-len
			}
			q = x[ ix ];
			if ( isAsc ) {
				a = v;
				b = q;
			} else {
				a = q;
				b = v;
			}
			if ( ( isRight ) ? ( a <= b ) : ( a < b ) ) {
				out[ io ] = mid;
			}
			ix += strideX;
			io += strideOut;
		}
		length -= half;
	}
	// Final level: each insertion index is either `base` or `base+1`...
	ix = offsetX;
	io = offsetOut;
	for ( i = 0; i < M; i++ ) {
		q = x[ ix ];

		// If the search element is `NaN`, set the insertion index to `-1`...
		if ( isnan( q ) ) {
			out[ io ] = -1;
		} else {
			base = out[ io ];
			v = search[ offsetSearch + ( base * strideSearch ) ];
			if ( isnan( v ) ) {
				return linear( M, N, fcn, x, strideX, offsetX, search, strideSearch, offsetSearch, out, strideOut, offsetOut ); // eslint-disable-line max-len
			}
			if ( isAsc ) {
				a = v;
				b = q;
			} else {
				a = q;
				b = v;
			}
			if ( ( isRight ) ? ( a <= b ) : ( a < b ) ) {
				out[ io ] = base + 1;
			}
		}
		ix += strideX;
		io += strideOut;
	}
	return out;
}


// EXPORTS //

module.exports = gsearchSorted;
